async function ensureWebPushVapid() {
    if (!webPushVapidPromise)
        webPushVapidPromise = (async () => {
            const envPublic = String(process.env.WEB_PUSH_VAPID_PUBLIC_KEY || '').trim();
            const envPrivate = String(process.env.WEB_PUSH_VAPID_PRIVATE_KEY || '').trim();
            let publicKey = envPublic, privateKey = envPrivate;
            if (!publicKey || !privateKey) {
                let q = await pool.query(`SELECT value FROM platform_settings WHERE key=$1 LIMIT 1`, [WEB_PUSH_SETTING_KEY]).catch(() => ({ rows: [] }));
                const saved = q.rows[0]?.value || {};
                publicKey = String(saved.publicKey || '').trim();
                privateKey = String(saved.privateKey || '').trim();
                if (!publicKey || !privateKey) {
                    const generated = webpush.generateVAPIDKeys();
                    await pool.query(`INSERT INTO platform_settings(key,value,updated_at) VALUES($1,$2::jsonb,now()) ON CONFLICT(key) DO NOTHING`, [WEB_PUSH_SETTING_KEY, JSON.stringify({ publicKey: generated.publicKey, privateKey: generated.privateKey, generatedAt: new Date().toISOString() })]);
                    q = await pool.query(`SELECT value FROM platform_settings WHERE key=$1 LIMIT 1`, [WEB_PUSH_SETTING_KEY]);
                    const row = q.rows[0]?.value || generated;
                    publicKey = String(row.publicKey || generated.publicKey || '').trim();
                    privateKey = String(row.privateKey || generated.privateKey || '').trim();
                }
            }
            if (!publicKey || !privateKey) throw new Error('web_push_vapid_unavailable');
            webpush.setVapidDetails(WEB_PUSH_SUBJECT, publicKey, privateKey);
            return { publicKey, privateKey };
        })().catch((e) => { webPushVapidPromise = null; throw e; });
    return webPushVapidPromise;
}

