function maintenanceAdminRequestAllowed(req, url, primaryAdmin) {
    if (!primaryAdmin)
        return false;
    const pathname = url.pathname;
    const portal = requestPortal(req);
    // The primary admin may use the admin SPA and any API call explicitly made
    // from that SPA. Merely having an admin cookie does not unlock role portals.
    if ((req.method === 'GET' || req.method === 'HEAD') && (pathname === '/admin' || pathname === '/admin/' || pathname.startsWith('/admin/')))
        return true;
    if (pathname.startsWith('/api/') && portal === 'admin')
        return true;
    // The owner can open registration shells while maintenance is active in order
    // to create dedicated test roles with the same primary-admin mobile number.
    if ((req.method === 'GET' || req.method === 'HEAD') && (pathname === '/trial' || pathname === '/photographer/signup' || pathname === '/equipment-rental/register'))
        return true;
    if (pathname === '/api/public/lab-trial' || pathname === '/api/public/lab-trial/verify'
        || pathname === '/api/public/photographer-signup' || pathname === '/api/public/photographer-signup/verify'
        || pathname === '/api/public/equipment-rental-trial' || pathname === '/api/public/equipment-rental-trial/verify')
        return true;
    // Explicit preview shells let the primary admin reach the login screen. A
    // regular user's role cookie is still blocked by the role-session bypass check.
    const previewShell = (req.method === 'GET' || req.method === 'HEAD')
        && (pathname === '/lab' || pathname === '/lab/' || pathname === '/photographer' || pathname === '/photographer/' || pathname === '/rental' || pathname === '/rental/')
        && url.searchParams.get('maintenance_preview') === '1';
    if (previewShell)
        return true;
    if (pathname === '/api/auth/lab-login' || pathname === '/api/auth/customer-login' || pathname === '/api/auth/rental-login' || pathname === '/api/auth/logout')
        return true;
    if (pathname === '/api/auth/me' && (portal === 'lab' || portal === 'photographer' || portal === 'rental') && !cookie(req, sessionCookieName(portal)))
        return true;
    if (pathname.startsWith('/api/') && isAdminImpersonationRequest(req))
        return true;
    return false;
}
