function sanitizeLabQuickAccess(raw, useProductDefault = true) {
    const value = raw?.quickAccess || raw || {};
    const unique = (input, max) => Array.isArray(input) ? input.map((x) => String(x || '').trim()).filter(Boolean).filter((x, i, a) => a.indexOf(x) === i && LAB_QUICK_ACCESS_IDS.includes(x)).slice(0, max) : [];
    let pinned = Array.isArray(value.pinned) ? unique(value.pinned, 10) : (useProductDefault ? [...LAB_QUICK_ACCESS_DEFAULT] : []);
    if (useProductDefault) {
        const rest = pinned.filter((x) => !LAB_QUICK_ACCESS_REQUIRED_DEFAULT.includes(x));
        pinned = [...LAB_QUICK_ACCESS_REQUIRED_DEFAULT, ...rest].slice(0, 10);
    }
    const menuEnabled = Boolean(value.menuEnabled);
    let menuItems = unique(value.menuItems, 8).filter((x) => pinned.includes(x));
    if (menuEnabled && !menuItems.length)
        menuItems = pinned.slice(0, 8);
    return { pinned, menuEnabled, menuItems };
}
