    const token = decryptSnappboxSecret(String(r.snappbox_api_token_encrypted || ''));
    return { labId, enabled: Boolean(r.snappbox_enabled), environment: String(r.snappbox_environment || 'production') === 'staging' ? 'staging' : 'production', token, tokenStored: Boolean(token), pickupLat: r.pickup_lat == null ? null : Number(r.pickup_lat), pickupLng: r.pickup_lng == null ? null : Number(r.pickup_lng), pickupAddress: String(r.pickup_address || ''), pickupContactName: String(r.pickup_contact_name || r.lab_name || r.lab_admin_name || ''), pickupPhone: String(r.pickup_phone || r.lab_admin_mobile || ''), defaultDeliveryCategory: String(r.default_delivery_category || 'bike-without-box'), labName: String(r.lab_name || 'لابراتوار') };
