        try {
            data = text ? JSON.parse(text) : {};
        }
        catch {
            data = { message: text.slice(0, 500) };
        }
        if (!r.ok) {
            const detail = String(data?.message || data?.error || data?.key || `HTTP ${r.status}`).slice(0, 500);
            throw Object.assign(new Error('snappbox_request_failed'), { status: r.status, detail, data });
        }
