async function syncSnappboxShipmentFromProvider(row, settings) {
    if (!row?.provider_order_id)
        return row;
    const cfg = settings || await labDeliverySettings(String(row.lab_id));
    if (!cfg?.enabled || !cfg?.tokenStored)
        return row;
    const data = await snappboxRequest(cfg, `/v1/orders/${encodeURIComponent(String(row.provider_order_id))}`, { method: 'GET' });
    const details = snappboxDriverDetails(data, String(row.delivery_category || ''));
    const status = String(data?.status || row.status || '');
    const q = await pool.query(`UPDATE order_courier_shipments SET status=$3,raw_response=COALESCE(raw_response,'{}'::jsonb) || $4::jsonb,driver_name=COALESCE(NULLIF($5,''),driver_name),driver_phone=COALESCE(NULLIF($6,''),driver_phone),vehicle_plate=COALESCE(NULLIF($7,''),vehicle_plate),driver_image_url=COALESCE(NULLIF($8,''),driver_image_url),driver_details_updated_at=now(),updated_at=now() WHERE id=$1 AND lab_id=$2 RETURNING *`, [row.id, row.lab_id, status || null, JSON.stringify(data || {}), details.driverName, details.driverPhone, details.vehiclePlate, details.driverImageUrl]);
    const updated = q.rows[0] || row;
    const changed = String(row.status || '') !== String(updated.status || '') || String(row.driver_name || '') !== String(updated.driver_name || '') || String(row.driver_phone || '') !== String(updated.driver_phone || '') || String(row.vehicle_plate || '') !== String(updated.vehicle_plate || '');
    if (changed) {
        const oq = await pool.query(`SELECT customer_id,number FROM orders WHERE id=$1 AND lab_id=$2 LIMIT 1`, [row.order_id, row.lab_id]);
        if (oq.rowCount)
            publishCustomerEvent(String(row.lab_id), String(oq.rows[0].customer_id), 'courier_update', { orderId: row.order_id, number: oq.rows[0].number, status: updated.status, payer: updated.payer, quotedPrice: Number(updated.quoted_price || 0), driverName: updated.driver_name || '', driverPhone: updated.driver_phone || '', vehiclePlate: updated.vehicle_plate || '', deliveryCategory: updated.delivery_category || '', alertAcknowledged: Boolean(updated.photographer_alert_ack_at) });
    }
    return updated;
}
async function refreshActiveSnappboxShipments() {
    const q = await pool.query(`SELECT cs.* FROM order_courier_shipments cs JOIN orders o ON o.id=cs.order_id WHERE cs.provider='snappbox' AND cs.provider_order_id IS NOT NULL AND COALESCE(upper(cs.status),'') NOT IN ('DELIVERED','CANCELLED') AND cs.created_at>now()-interval '2 days' ORDER BY cs.updated_at ASC LIMIT 30`);
    const settingsCache = new Map();
    for (const row of q.rows) {
        try {
            let settings = settingsCache.get(String(row.lab_id));
            if (!settings) {
                settings = await labDeliverySettings(String(row.lab_id));
                settingsCache.set(String(row.lab_id), settings);
            }
            await syncSnappboxShipmentFromProvider(row, settings);
        }
        catch (e) {
            if (String(e?.message || '') !== 'snappbox_not_configured')
                console.warn('SnappBox background refresh failed', row.id, String(e?.detail || e?.message || e));
        }
    }
}
async function snappboxOrderContext(labId, orderId) {
    const [sq, oq] = await Promise.all([
        labDeliverySettings(labId),
        pool.query(`SELECT o.id,o.number,o.status,o.total,o.customer_id,COALESCE(o.walkin_customer_name,u.name) customer_name,COALESCE(o.walkin_customer_mobile,u.mobile) customer_mobile,u.location_lat,u.location_lng,
      COALESCE((SELECT count(*)::int FROM order_files f WHERE f.order_id=o.id),0) file_count,
      i.total invoice_total
      FROM orders o JOIN users u ON u.id=o.customer_id LEFT JOIN invoices i ON i.order_id=o.id WHERE o.id=$1 AND o.lab_id=$2 LIMIT 1`, [orderId, labId])
    ]);
    if (!oq.rowCount)
        throw Object.assign(new Error('order_not_found'), { status: 404 });
    const o = oq.rows[0];
    if (!sq.enabled || !sq.tokenStored)
        throw Object.assign(new Error('snappbox_not_configured'), { status: 409 });
    if (!Number.isFinite(Number(sq.pickupLat)) || !Number.isFinite(Number(sq.pickupLng)))
        throw Object.assign(new Error('snappbox_pickup_location_missing'), { status: 409 });
    if (!Number.isFinite(Number(o.location_lat)) || !Number.isFinite(Number(o.location_lng)))
        throw Object.assign(new Error('photographer_location_missing'), { status: 409 });
    if (!String(sq.pickupPhone || '').trim())
        throw Object.assign(new Error('snappbox_pickup_phone_missing'), { status: 409 });
    if (!String(o.customer_mobile || '').trim())
        throw Object.assign(new Error('photographer_phone_missing'), { status: 409 });
    return { settings: sq, order: o, pickup: snappboxTerminal({ type: 'pickup', reference: '1', lat: sq.pickupLat, lng: sq.pickupLng, address: sq.pickupAddress, contactName: sq.pickupContactName || sq.labName, phone: sq.pickupPhone, comment: `PhotoBridge سفارش #${o.number}` }), drop: snappboxTerminal({ type: 'drop', reference: '2', lat: o.location_lat, lng: o.location_lng, address: 'موقعیت ثبت‌شده عکاسی در PhotoBridge', contactName: o.customer_name, phone: o.customer_mobile, comment: `تحویل سفارش چاپ #${o.number}` }) };
}
