async function runAdminAiRetouchGuidedToFinal(jobId, userId, ownerType = 'admin') {
    const owner = ownerType === 'lab' ? 'lab' : ownerType === 'customer' ? 'customer' : ownerType === 'public' ? 'public' : 'admin';
    try {
        let q = await pool.query(`SELECT status,metadata FROM ai_image_jobs WHERE id=$1 AND owner_type='${owner}' AND owner_id=$2 LIMIT 1`, [jobId, userId]);
        if (!q.rowCount)
            return;
        let row = q.rows[0], phase = String(row?.metadata?.debugPhase || '');
        if (row.status === 'completed' || phase === 'final_ready') {
            if (owner === 'admin')
                await applyAdminRetouchLowResEnhancementIfSelected(jobId, userId);
            if (owner === 'public')
                await syncPublicAiOrderFromJob(jobId);
            return;
        }
        if (phase === 'crop_ready') {
            await processAdminAiRetouchDebugAiStage(jobId, userId, ownerType);
            q = await pool.query(`SELECT status,metadata FROM ai_image_jobs WHERE id=$1 AND owner_type='${owner}' AND owner_id=$2 LIMIT 1`, [jobId, userId]);
            if (!q.rowCount)
                return;
            row = q.rows[0];
            phase = String(row?.metadata?.debugPhase || '');
        }
        if (row.status === 'completed' || phase === 'final_ready') {
            if (owner === 'admin')
                await applyAdminRetouchLowResEnhancementIfSelected(jobId, userId);
            if (owner === 'public')
                await syncPublicAiOrderFromJob(jobId);
            return;
        }
        if (Boolean(row?.metadata?.debugPauseRequestedAt) || Boolean(row?.metadata?.debugPaused))
            return;
        if (phase === 'ai_processing' || phase === 'compositing')
            return;
        if (phase === 'ai_ready' || phase === 'composite_failed') {
            for (let attempt = 0; attempt < 2; attempt++) {
                try {
                    await finalizeAdminAiRetouchDebugJob(jobId, userId, ownerType);
                    if (owner === 'admin')
                        await applyAdminRetouchLowResEnhancementIfSelected(jobId, userId);
                    if (owner === 'public')
                        await syncPublicAiOrderFromJob(jobId);
                    return;
                }
                catch (e) {
                    if (attempt > 0)
                        throw e;
                    await new Promise(resolve => setTimeout(resolve, 1200));
                    const rq = await pool.query(`SELECT status,metadata FROM ai_image_jobs WHERE id=$1 AND owner_type='${owner}' AND owner_id=$2 LIMIT 1`, [jobId, userId]);
                    const rr = rq.rows?.[0];
                    if (!rr || rr.status === 'completed' || String(rr?.metadata?.debugPhase || '') === 'final_ready')
                        return;
                    if (String(rr?.metadata?.debugPhase || '') !== 'composite_failed')
                        throw e;
                }
            }
        }
    }
    catch (e) {
        const code = String(e?.message || e?.code || '');
        if (code === 'ai_stage4_capacity_busy') {
            // v0.17.556: when this job belongs to the durable queue, the queue runner
            // owns retries. Do not create a second out-of-band runner that could overlap
            // the next queued job. Legacy/admin-only jobs keep the old fallback.
            const queued = await pool.query(`SELECT state FROM ai_retouch_queue WHERE job_id=$1 LIMIT 1`, [jobId]).catch(() => ({ rows: [] }));
            if (queued.rows?.[0])
                return;
            const t = setTimeout(() => void runAdminAiRetouchGuidedToFinal(jobId, userId, ownerType), 2500);
            t.unref?.();
            return;
        }
        console.error('Guided retouch background flow stopped', { jobId, userId, ownerType: owner, error: e?.message, code: e?.code });
        if (owner === 'customer') {
            const fq = await pool.query(`SELECT * FROM ai_image_jobs WHERE id=$1 AND owner_type='customer' AND owner_id=$2 LIMIT 1`, [jobId, userId]).catch(() => ({ rows: [] }));
            const fr = fq.rows?.[0];
            if (fr?.status === 'failed')
                await refundAiJobReservation(fr, String(fr.error_code || e?.message || 'guided_failed')).catch(() => { });
        }
        if (owner === 'public')
            await syncPublicAiOrderFromJob(jobId).catch(() => { });
    }
}
