async function syncPublicAiOrderFromJob(jobId) {
    const q = await pool.query(`SELECT o.id,o.access_token,o.status,j.status job_status,j.error_code,j.metadata job_metadata,q.state queue_state,q.attempt_count queue_attempt_count,q.max_attempts queue_max_attempts FROM public_ai_orders o JOIN ai_image_jobs j ON j.id=o.ai_job_id LEFT JOIN ai_retouch_queue q ON q.job_id=j.id WHERE o.ai_job_id=$1 LIMIT 1`, [jobId]);
    if (!q.rowCount)
        return null;
    const r = q.rows[0];
    if (r.job_status === 'completed') {
        const uq = await pool.query(`UPDATE public_ai_orders SET status='completed',completed_at=COALESCE(completed_at,now()),updated_at=now() WHERE id=$1 AND status<>'completed' RETURNING *`, [r.id]);
        await ensureRetouchOutputExpiry(jobId).catch(() => { });
        if (uq.rowCount) {
            const t = setTimeout(() => void notifyPublicAiOrderIfNeeded(String(r.id)).catch(() => { }), 5_000);
            t.unref?.();
            const next = setTimeout(() => void publicAiProcessingSweep().catch(() => { }), 250);
            next.unref?.();
        }
        return uq.rows[0] || r;
    }
    if (r.job_status === 'failed') {
        const phase = String(r.job_metadata?.debugPhase || ''), qs = String(r.queue_state || ''), qa = Number(r.queue_attempt_count || 0), qm = Math.max(1, Number(r.queue_max_attempts || 6));
        if (phase === 'composite_failed' && ['waiting','running'].includes(qs) && qa < qm) {
            const uq = await pool.query(`UPDATE public_ai_orders SET status='processing',completed_at=NULL,updated_at=now() WHERE id=$1 AND status NOT IN ('completed','cancelled') RETURNING *`, [r.id]);
            return uq.rows[0] || r;
        }
        const uq = await pool.query(`UPDATE public_ai_orders SET status='failed',completed_at=COALESCE(completed_at,now()),metadata=COALESCE(metadata,'{}'::jsonb)||$2::jsonb,updated_at=now() WHERE id=$1 AND status NOT IN ('completed','cancelled') RETURNING *`, [r.id, JSON.stringify({ aiErrorCode: r.error_code || 'ai_failed' })]);
        if (uq.rowCount) {
            const next = setTimeout(() => void publicAiProcessingSweep().catch(() => { }), 250);
            next.unref?.();
        }
        return uq.rows[0] || r;
    }
    return r;
}
async function notifyPublicAiOrderIfNeeded(orderId) {
    const q = await pool.query(`SELECT o.*,p.title plan_title,j.output_expires_at,j.output_deleted_at FROM public_ai_orders o JOIN public_ai_plans p ON p.id=o.plan_id LEFT JOIN ai_image_jobs j ON j.id=o.ai_job_id WHERE o.id=$1 LIMIT 1`, [orderId]);
    if (!q.rowCount) return;
    const o = q.rows[0];
    if (o.status !== 'completed' || o.downloaded_at || o.output_deleted_at) return;
    const readyAt = new Date(o.completed_at || o.updated_at || Date.now()).getTime();
    if (Date.now() - readyAt < 3_000) return;
    if (!o.output_expires_at && o.ai_job_id) {
        await ensureRetouchOutputExpiry(String(o.ai_job_id)).catch(() => { });
        return notifyPublicAiOrderIfNeeded(orderId);
    }
    const link = publicAiOrderUrl(String(o.access_token)), expiryText = formatRetouchExpiryFa(o.output_expires_at || o.access_expires_at), ordersUrl = `${PUBLIC_APP_URL}/retouch-account`;
    if (!o.ready_sms_sent_at) {
        try {
            await sendSms({ mobile: String(o.contact_mobile), message: `PhotoBridge: روتوش «${String(o.plan_title || 'عکس شما')}» آماده است.\nدریافت فایل: ${link}\nمهلت دانلود: ${expiryText || 'طبق زمان نمایش‌داده‌شده در صفحه سفارش'}\nبعد از پایان این مهلت فایل به‌صورت خودکار از سرور حذف می‌شود.\nسفارش‌های من: ${ordersUrl}`, purpose: 'public_ai_ready', eventKey: 'public_ai_ready', userId: o.user_id || undefined, metadata: { publicAiOrderId: o.id, expiresAt: o.output_expires_at || o.access_expires_at || null } });
            await pool.query(`UPDATE public_ai_orders SET ready_sms_status='sent',ready_sms_sent_at=now(),ready_email_status='disabled',ready_email_sent_at=COALESCE(ready_email_sent_at,now()),updated_at=now() WHERE id=$1`, [o.id]);
        }
        catch (e) {
            await pool.query(`UPDATE public_ai_orders SET ready_sms_status=$2,updated_at=now() WHERE id=$1`, [o.id, String(e?.message || 'failed').slice(0, 80)]).catch(() => { });
        }
    }
}
async function publicAiReadyDeliverySweep() {
    const q = await pool.query(`SELECT id FROM public_ai_orders WHERE status='completed' AND downloaded_at IS NULL AND completed_at<=now()-interval '5 seconds' AND ready_sms_sent_at IS NULL ORDER BY completed_at ASC LIMIT 25`).catch(() => ({ rows: [] }));
    for (const r of q.rows || []) await notifyPublicAiOrderIfNeeded(String(r.id)).catch(() => { });
}
