async function ensurePublicPhotographerSignupRuntimeSchema() {
    if (publicPhotographerSignupSchemaReady)
        return;
    if (!publicPhotographerSignupSchemaPromise)
        publicPhotographerSignupSchemaPromise = repairPublicPhotographerSignupRuntimeSchema();
    try {
        await publicPhotographerSignupSchemaPromise;
        publicPhotographerSignupSchemaReady = true;
    }
    finally {
        publicPhotographerSignupSchemaPromise = null;
    }
}
async function notifyPlatformAdminSms(eventKey, message, labId) {
    const cfg = await resolvedSMSSettings();
    if (!cfg.configured || !cfg.notificationsEnabled || !cfg.adminAlertsEnabled || cfg.events?.[eventKey] === false)
        return;
    const q = await pool.query(`SELECT id,mobile FROM users WHERE platform_role='platform_admin' AND active=true AND mobile IS NOT NULL ORDER BY created_at LIMIT 1`);
    if (!q.rowCount)
        return;
    await sendSms({ mobile: q.rows[0].mobile, message, purpose: 'admin_alert', eventKey, userId: q.rows[0].id, labId: labId || null, requireNotificationsEnabled: true });
}
async function notifyLabCustomerForStatus(labId, customerId, status, order, invoice) {
    if (!['sent', 'received', 'ready', 'completed'].includes(status))
        return;
    const q = await pool.query(`SELECT l.name lab_name,l.sms_customer_notifications_allowed,u.mobile,u.name,s.enabled sms_enabled,
      s.order_submitted_enabled,s.order_received_enabled,s.order_ready_enabled,s.order_completed_enabled,s.invoice_enabled
    FROM labs l JOIN users u ON u.id=$2 LEFT JOIN lab_sms_settings s ON s.lab_id=l.id WHERE l.id=$1`, [labId, customerId]);
    if (!q.rowCount)
        return;
    const r = q.rows[0];
    if (!r.sms_customer_notifications_allowed || !r.sms_enabled)
        return;
    if (status === 'sent' && !r.order_submitted_enabled)
        return;
    if (status === 'received' && !r.order_received_enabled)
        return;
    if (status === 'ready' && !r.order_ready_enabled)
        return;
    if (status === 'completed' && !r.order_completed_enabled)
        return;
    if (order?.id) {
        const sent = await pool.query(`SELECT id FROM sms_delivery_log WHERE lab_id=$1 AND purpose='lab_customer_notification' AND event_key=$2 AND status='sent' AND metadata->>'orderId'=$3 LIMIT 1`, [labId, `order_${status}`, String(order.id)]);
        if (sent.rowCount)
            return;
    }
    const textByStatus = {
        sent: `PhotoBridge: سفارش #${order.number} شما در ${r.lab_name} با موفقیت ثبت شد.`,
        received: `PhotoBridge: سفارش #${order.number} شما توسط ${r.lab_name} دریافت شد و در حال بررسی است.`,
        ready: `PhotoBridge: سفارش #${order.number} شما در ${r.lab_name} آماده تحویل است.`,
        completed: `PhotoBridge: سفارش #${order.number} شما در ${r.lab_name} تحویل/تکمیل شد.`
    };
    let text = textByStatus[status] || `PhotoBridge: وضعیت سفارش #${order.number} شما در ${r.lab_name} به‌روزرسانی شد.`;
    if (status === 'ready' && invoice && r.invoice_enabled)
        text += ` مبلغ فاکتور: ${Number(invoice.total || 0).toLocaleString('fa-IR')}`;
    await sendSms({ mobile: r.mobile, message: text, purpose: 'lab_customer_notification', eventKey: `order_${status}`, userId: customerId, labId, chargeLabId: labId, serviceKey: 'sms_customer_notification', metadata: { orderId: order.id || null, orderNumber: order.number || null } });
}
async function notifyLabManagerSms(labId, eventKey, payload) {
    const q = await pool.query(`SELECT l.name lab_name,l.sms_customer_notifications_allowed,u.id user_id,u.name admin_name,u.mobile,s.enabled sms_enabled,
      s.manager_order_submitted_enabled,s.manager_chat_enabled
    FROM labs l
    LEFT JOIN lab_sms_settings s ON s.lab_id=l.id
    JOIN LATERAL (
      SELECT u.id,u.name,u.mobile FROM lab_memberships m JOIN users u ON u.id=m.user_id
      WHERE m.lab_id=l.id AND m.role='lab_admin' AND m.active=true AND u.active=true
      ORDER BY m.created_at LIMIT 1
    ) u ON true
    WHERE l.id=$1`, [labId]);
    if (!q.rowCount)
        return;
    const r = q.rows[0];
    if (!r.sms_customer_notifications_allowed || !r.sms_enabled)
        return;
    if (eventKey === 'manager_order_submitted' && !r.manager_order_submitted_enabled)
        return;
    if (eventKey === 'manager_chat' && !r.manager_chat_enabled)
        return;
    const mobile = normalizeMobile(String(r.mobile || ''));
    if (!/^09\d{9}$/.test(mobile))
        return;
    if (eventKey === 'manager_order_submitted' && payload?.orderId) {
        const sent = await pool.query(`SELECT id FROM sms_delivery_log WHERE lab_id=$1 AND purpose='lab_manager_notification' AND event_key=$2 AND status='sent' AND metadata->>'orderId'=$3 LIMIT 1`, [labId, eventKey, String(payload.orderId)]);
        if (sent.rowCount)
            return;
    }
    let message = '';
    if (eventKey === 'manager_order_submitted') {
        const files = Number(payload?.files || 0);
        message = `PhotoBridge: سفارش جدید #${payload?.number || '—'} از «${String(payload?.customerName || 'عکاس')}» ثبت شد${files ? ` · ${files.toLocaleString('fa-IR')} فایل` : ''}.`;
    }
    else {
        const text = String(payload?.message || '').replace(/\s+/g, ' ').trim().slice(0, 170);
        message = `PhotoBridge: پیام جدید از «${String(payload?.senderName || 'عکاس')}» در گفتگوهای ${r.lab_name}${text ? `: ${text}` : '.'}`;
    }
    await sendSms({ mobile, message, purpose: 'lab_manager_notification', eventKey, userId: r.user_id, labId, chargeLabId: labId, serviceKey: 'sms_customer_notification', metadata: { ...(payload || {}), recipientRole: 'lab_admin' } });
}
async function mobileAlreadyRegistered(mobile) {
    const q = await pool.query(`SELECT mobile FROM users WHERE mobile IS NOT NULL`);
    return q.rows.some((r) => normalizeMobile(String(r.mobile || '')) === mobile);
}
async function mobileAlreadyMemberOfLab(labId, mobile, db = pool) {
    const q = await db.query(`SELECT u.id,u.mobile FROM lab_memberships m JOIN users u ON u.id=m.user_id WHERE m.lab_id=$1 AND m.role='customer' AND m.active=true AND u.mobile IS NOT NULL`, [labId]);
    return q.rows.some((r) => normalizeMobile(String(r.mobile || '')) === mobile);
}
async function labPhotographerPriorRelationship(db, labId, mobileValue) {
    const mobile = normalizeMobile(String(mobileValue || ''));
    if (!/^09\d{9}$/.test(mobile))
        return { previousRelationship: false, activeMember: false, customerId: null, previousBalance: 0, invoiceCount: 0 };
    const uq = await db.query(`SELECT u.id::text,COALESCE(pp.studio_name,u.name) name,u.mobile FROM users u LEFT JOIN photographer_profiles pp ON pp.user_id=u.id WHERE right(regexp_replace(COALESCE(u.mobile,''),'\D','','g'),10)=right(regexp_replace($1,'\D','','g'),10) ORDER BY u.photographer_enabled DESC,u.created_at DESC LIMIT 1`, [mobile]);
    if (!uq.rowCount)
        return { previousRelationship: false, activeMember: false, customerId: null, previousBalance: 0, invoiceCount: 0 };
    const user = uq.rows[0];
    const hq = await db.query(`SELECT
      EXISTS(SELECT 1 FROM lab_memberships WHERE lab_id::text=$1::text AND user_id::text=$2::text AND role='customer' AND active=true) active_member,
      EXISTS(SELECT 1 FROM audit_log WHERE lab_id::text=$1::text AND action='customer.remove' AND entity_type='user' AND entity_id::text=$2::text) removed_before,
      EXISTS(SELECT 1 FROM invoices i LEFT JOIN orders o ON o.id=i.order_id
        WHERE i.lab_id::text=$1::text AND i.customer_id::text=$2::text
        AND COALESCE(o.source,'')<>'lab_delegated') has_invoices,
      EXISTS(SELECT 1 FROM orders o WHERE o.lab_id::text=$1::text AND o.customer_id::text=$2::text
        AND o.source<>'lab_delegated') has_orders,
      EXISTS(SELECT 1 FROM accounting_party_mappings WHERE lab_id::text=$1::text AND customer_id::text=$2::text) has_accounting,
      (SELECT count(*)::int FROM invoices WHERE lab_id::text=$1::text AND customer_id::text=$2::text) invoice_count`, [String(labId), String(user.id)]);
    const h = hq.rows[0] || {};
    let previousBalance = 0;
    try { previousBalance = Number(await customerReceivableBalance(db, labId, user.id) || 0); } catch {}
    return { previousRelationship: Boolean(h.removed_before || h.has_invoices || h.has_orders || h.has_accounting), activeMember: Boolean(h.active_member), customerId: user.id, customerName: String(user.name || ''), previousBalance, invoiceCount: Number(h.invoice_count || 0), removedBefore: Boolean(h.removed_before) };
}

async function photographerInitialInviteType(userId) {
    const uq = await pool.query(`SELECT photographer_origin_invite_type,photographer_joined_at FROM users WHERE id=$1 LIMIT 1`, [userId]);
    const persisted = String(uq.rows[0]?.photographer_origin_invite_type || '').trim();
    if (['admin','lab','photographer','rental'].includes(persisted))
        return persisted;
    // Legacy fallback: only events that actually created the photographer role are candidates.
    // Later lab invitations accepted by an already-existing photographer must never change the
    // initial origin and therefore must not remove public lab discovery.
    const q = await pool.query(`WITH candidates AS (
      SELECT i.issuer_type::text origin_type,r.redeemed_at event_at,1 priority
      FROM photographer_invite_redemptions r
      JOIN photographer_invites i ON i.id=r.invite_id
      JOIN users u ON u.id=r.user_id
      WHERE r.user_id=$1
        AND i.issuer_type IN ('admin','lab','photographer','rental')
        AND lower(COALESCE(r.metadata->>'wasPhotographer','false')) NOT IN ('true','1','yes')
        AND (u.photographer_joined_at IS NULL OR r.redeemed_at<=u.photographer_joined_at+interval '15 minutes')
      UNION ALL
      SELECT 'lab'::text,a.created_at,2
      FROM audit_log a JOIN users u ON u.id=$1
      WHERE a.entity_type='user' AND a.entity_id::text=$1::text
        AND a.action='invitation.register' AND a.lab_id IS NOT NULL
        AND lower(COALESCE(a.data->>'reusedExistingCustomer','false')) NOT IN ('true','1','yes')
        AND (u.photographer_joined_at IS NULL OR a.created_at<=u.photographer_joined_at+interval '15 minutes')
      UNION ALL
      SELECT CASE WHEN a.data->>'issuerType' IN ('admin','lab','photographer','rental') THEN a.data->>'issuerType'
                  WHEN a.lab_id IS NOT NULL THEN 'lab' ELSE NULL END,a.created_at,3
      FROM audit_log a JOIN users u ON u.id=$1
      WHERE a.entity_type='user' AND a.entity_id::text=$1::text
        AND a.action='photographer.invite_redeem'
        AND lower(COALESCE(a.data->>'reusedExisting','false')) NOT IN ('true','1','yes')
        AND (u.photographer_joined_at IS NULL OR a.created_at<=u.photographer_joined_at+interval '15 minutes')
    ) SELECT origin_type FROM candidates WHERE origin_type IS NOT NULL ORDER BY event_at ASC,priority ASC LIMIT 1`, [userId]);
    const inferred = String(q.rows[0]?.origin_type || '').trim();
    if (!['admin','lab','photographer','rental'].includes(inferred))
        return '';
    await pool.query(`UPDATE users SET photographer_origin_invite_type=COALESCE(photographer_origin_invite_type,$2),updated_at=now() WHERE id=$1`, [userId, inferred]).catch(() => { });
    return inferred;
}
async function photographerInitialOriginContext(userId) {
    const originType = await photographerInitialInviteType(userId);
    let primaryLabId = null, primaryShopId = null;
    if (originType === 'lab') {
        const q = await pool.query(`SELECT i.issuer_lab_id::text id FROM photographer_invite_redemptions r JOIN photographer_invites i ON i.id=r.invite_id WHERE r.user_id=$1 AND i.issuer_type='lab' AND i.issuer_lab_id IS NOT NULL AND lower(COALESCE(r.metadata->>'wasPhotographer','false')) NOT IN ('true','1','yes') ORDER BY r.redeemed_at ASC LIMIT 1`, [userId]);
        primaryLabId = String(q.rows[0]?.id || '');
        if (!primaryLabId) {
            const f = await pool.query(`SELECT m.lab_id::text id FROM lab_memberships m JOIN labs l ON l.id=m.lab_id WHERE m.user_id=$1 AND m.role='customer' AND m.active=true AND l.service_only=false ORDER BY m.created_at ASC LIMIT 1`, [userId]);
            primaryLabId = String(f.rows[0]?.id || '');
        }
    } else if (originType === 'rental') {
        const q = await pool.query(`SELECT i.issuer_rental_shop_id::text id FROM photographer_invite_redemptions r JOIN photographer_invites i ON i.id=r.invite_id WHERE r.user_id=$1 AND i.issuer_type='rental' AND i.issuer_rental_shop_id IS NOT NULL AND lower(COALESCE(r.metadata->>'wasPhotographer','false')) NOT IN ('true','1','yes') ORDER BY r.redeemed_at ASC LIMIT 1`, [userId]);
        primaryShopId = String(q.rows[0]?.id || '');
        if (!primaryShopId) {
            const f = await pool.query(`SELECT shop_id::text id FROM equipment_rental_shop_memberships WHERE user_id=$1 AND role='photographer' AND active=true ORDER BY created_at ASC LIMIT 1`, [userId]).catch(()=>({rows:[]}));
            primaryShopId = String(f.rows[0]?.id || '');
        }
    }
    return { originType, primaryLabId: primaryLabId || null, primaryShopId: primaryShopId || null };
}
async function photographerJoinedViaLabInvite(userId) {
    return (await photographerInitialInviteType(userId)) === 'lab';
}
async function photographerInvitedLabIds(userId) {
    const q = await pool.query(`SELECT DISTINCT lab_id::text lab_id FROM (
      SELECT i.issuer_lab_id lab_id,r.redeemed_at accepted_at
      FROM photographer_invite_redemptions r
      JOIN photographer_invites i ON i.id=r.invite_id
      WHERE r.user_id=$1 AND i.issuer_type='lab' AND i.issuer_lab_id IS NOT NULL
      UNION ALL
      SELECT a.lab_id,a.created_at
      FROM audit_log a
      WHERE a.entity_type='user' AND a.entity_id::text=$1::text
        AND a.lab_id IS NOT NULL AND a.action IN ('invitation.register','photographer.invite_redeem')
        AND (a.action='invitation.register' OR COALESCE(NULLIF(a.data->>'issuerType',''),'lab')='lab')
    ) accepted
    WHERE lab_id IS NOT NULL
    ORDER BY lab_id`, [userId]);
    const ids = q.rows.map((r) => String(r.lab_id || '')).filter(Boolean);
    if (ids.length)
        return ids;
    // Very old lab-origin accounts may predate redemption/audit retention. Never fall back to the
    // public directory for them; expose only their current confirmed real-lab membership.
    const fallback = await pool.query(`SELECT l.id::text lab_id
      FROM users u
      JOIN lab_memberships m ON m.user_id=u.id AND m.lab_id=u.photographer_active_lab_id AND m.role='customer' AND m.active=true
      JOIN labs l ON l.id=m.lab_id
      WHERE u.id=$1 AND l.service_only=false AND l.active=true AND COALESCE(l.suspended,false)=false
        AND (l.active_from IS NULL OR l.active_from<=now()) AND (l.active_until IS NULL OR l.active_until>=now())
      LIMIT 1`, [userId]);
    return fallback.rows.map((r) => String(r.lab_id || '')).filter(Boolean);
}
async function photographerCanDiscoverLabs(userId) {
    // Only the source that created the photographer role controls discovery. Accepting a lab invite
    // later does not change that source. Lab-origin photographers stay limited to accepted inviter labs.
    if (await photographerJoinedViaLabInvite(userId))
        return false;
    const q = await pool.query(`SELECT EXISTS(
    SELECT 1 FROM lab_memberships m JOIN labs l ON l.id=m.lab_id
    WHERE m.user_id=$1 AND m.role='customer' AND m.active=true AND l.service_only=true
  ) can_discover`, [userId]);
    return Boolean(q.rows[0]?.can_discover);
}

