async function resolvePasswordResetUser(portal, mobile) {
    const q = await pool.query(`SELECT u.id,u.name,u.mobile,u.platform_role,u.active,u.photographer_enabled,pp.studio_name photographer_name FROM users u LEFT JOIN photographer_profiles pp ON pp.user_id=u.id WHERE u.active=true AND u.mobile IS NOT NULL`);
    const matching = q.rows.filter((r) => normalizeMobile(String(r.mobile || '')) === mobile);
    const selected = [];
    for (const u of matching) {
        if (portal === 'admin') {
            if (u.platform_role === 'platform_admin')
                selected.push(u);
            continue;
        }
        if (portal === 'photographer' && !u.photographer_enabled)
            continue;
        if (portal === 'rental') {
            const rq = await pool.query(`SELECT m.shop_id FROM equipment_rental_shop_memberships m WHERE m.user_id=$1 AND m.role='shop_admin' AND m.active=true ORDER BY m.created_at LIMIT 2`, [u.id]);
            if (rq.rowCount) selected.push({ ...u, rental_shop_id: rq.rows[0].shop_id });
            continue;
        }
        const role = portal === 'lab' ? 'lab_admin' : 'customer';
        const mq = await pool.query(`SELECT m.lab_id FROM lab_memberships m JOIN labs l ON l.id=m.lab_id WHERE m.user_id=$1 AND m.role=$2 AND m.active=true AND ($2::text<>'customer' OR l.service_only=true OR (l.active=true AND COALESCE(l.suspended,false)=false AND (l.active_from IS NULL OR l.active_from<=now()) AND (l.active_until IS NULL OR l.active_until>=now()))) ORDER BY l.service_only DESC,m.created_at LIMIT 2`, [u.id, role]);
        if (mq.rowCount)
            selected.push({ ...u, name: portal === 'photographer' ? String(u.photographer_name || u.name || 'عکاسی') : u.name, lab_id: mq.rows[0].lab_id });
    }
    return selected.length === 1 ? selected[0] : selected.length > 1 ? 'ambiguous' : null;
}
