function cleanAlbumProjectEditorState(raw){
    if(!raw||typeof raw!=='object'||Array.isArray(raw))return {};
    let out={};try{out=JSON.parse(JSON.stringify(raw))}catch{return {}};
    if(out.photos&&typeof out.photos==='object'){for(const p of Object.values(out.photos)){if(p&&typeof p==='object')delete p.sourceUrl}}
    const encoded=JSON.stringify(out);if(encoded.length>750_000)throw new Error('album_project_editor_state_too_large');return out;
}
function albumProjectEditorStatePublic(raw){
    let out={};try{out=raw&&typeof raw==='object'?JSON.parse(JSON.stringify(raw)):typeof raw==='string'?JSON.parse(raw):{}}catch{out={}};
    if(out.photos&&typeof out.photos==='object'){for(const [slotId,p] of Object.entries(out.photos)){if(!p||typeof p!=='object')continue;const key=String(p.sourceKey||'');if(key)p.sourceUrl=storedObjectInlineUrl(key,String(p.sourceName||`${slotId}.jpg`),String(p.contentType||'image/jpeg'),24*3600)}}
    return out;
}
