function albumTariffPriceEntries(settings) {
    const out = new Map();
    for (const cover of Array.isArray(settings?.covers) ? settings.covers : []) {
        const sizeLabel = String(cover?.sizeLabel || '').trim(), material = String(cover?.materialName || cover?.name || 'جلد').trim(), model = String(cover?.modelName || 'مدل').trim();
        for (const color of Array.isArray(cover?.colors) ? cover.colors : []) {
            const colorName = String(color?.name || color?.colorValue || 'رنگ').trim(), value = Number(color?.price ?? cover?.price);
            if (Number.isFinite(value))
                out.set(`cover|${sizeLabel}|${material}|${model}|${colorName}`, { category: 'album_cover', categoryLabel: 'جلد آلبوم', sizeLabel, label: `${material} · ${model} · ${colorName}`, oldValue: null, newValue: value });
        }
    }
    for (const pkg of Array.isArray(settings?.packages) ? settings.packages : []) {
        const sizeLabel = String(pkg?.sizeLabel || '').trim(), model = String(pkg?.modelName || 'کیف / باکس').trim(), color = String(pkg?.colorName || pkg?.colorValue || 'رنگ').trim(), value = Number(pkg?.price);
        if (Number.isFinite(value))
            out.set(`package|${sizeLabel}|${model}|${color}`, { category: 'album_package', categoryLabel: 'کیف / باکس آلبوم', sizeLabel, label: `${model} · ${color}`, oldValue: null, newValue: value });
    }
    for (const extra of Array.isArray(settings?.extras) ? settings.extras : []) {
        const name = String(extra?.name || 'خدمت جانبی').trim(), mode = String(extra?.pricingMode || 'flat'), value = Number(extra?.price);
        if (Number.isFinite(value))
            out.set(`extra|${name}|${mode}`, { category: 'album_extra', categoryLabel: 'خدمات جانبی آلبوم', sizeLabel: '', label: name, oldValue: null, newValue: value });
    }
    return out;
}
function albumTariffPriceChanges(before, after) {
    const a = albumTariffPriceEntries(before), b = albumTariffPriceEntries(after), keys = new Set([...a.keys(), ...b.keys()]), changes = [];
    for (const key of keys) {
        const old = a.get(key), next = b.get(key), oldValue = old?.newValue ?? null, newValue = next?.newValue ?? null;
        if (oldValue === newValue)
            continue;
        const row = next || old;
        changes.push({ ...row, key, oldValue, newValue });
    }
    return changes;
}
