async function zibalPost(endpoint, payload) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 20_000);
    try {
        const r = await fetch(`https://gateway.zibal.ir/v1/${endpoint}`, { method: 'POST', signal: controller.signal, headers: { 'content-type': 'application/json', 'accept': 'application/json', 'user-agent': 'PhotoBridge/0.17.282' }, body: JSON.stringify(payload) });
        const raw = await r.text();
        let data = {};
        try {
            data = raw ? JSON.parse(raw) : {};
        }
        catch {
            data = { message: raw.slice(0, 500) };
        }
        if (!r.ok)
            throw Object.assign(new Error('zibal_http_error'), { status: r.status, data });
        return data;
    }
    finally {
        clearTimeout(timer);
    }
}
