async function handleKindergartenWalletZibalCallback(res, url) {
    const trackId = String(url.searchParams.get('trackId') || '').trim();
    const orderId = String(url.searchParams.get('orderId') || '').trim();
    const success = String(url.searchParams.get('success') || '0') === '1';
    let q = { rows: [], rowCount: 0 };
    if (orderId)
        q = await pool.query(`SELECT * FROM kindergarten_wallet_gateway_payments WHERE id=$1 LIMIT 1`, [orderId]).catch(() => ({ rows: [], rowCount: 0 }));
    if (!q.rowCount && trackId)
        q = await pool.query(`SELECT * FROM kindergarten_wallet_gateway_payments WHERE gateway_track_id=$1 LIMIT 1`, [trackId]).catch(() => ({ rows: [], rowCount: 0 }));
    if (!q.rowCount)
        return redirect(res, `${PUBLIC_APP_URL}/?walletPayment=failed`);
    let row = q.rows[0];
    if (!trackId || (row.gateway_track_id && String(row.gateway_track_id) !== trackId))
        return redirect(res, kindergartenWalletReturnUrl(row, 'failed'));
    if (['paid', 'credit_pending', 'credited'].includes(String(row.status)))
        return redirect(res, kindergartenWalletReturnUrl(row, 'success'));
    if (!success) {
        await pool.query(`UPDATE kindergarten_wallet_gateway_payments SET status='payment_failed',gateway_message='پرداخت توسط کاربر کامل نشد',updated_at=now() WHERE id=$1 AND status NOT IN ('paid','credit_pending','credited')`, [row.id]).catch(() => { });
        return redirect(res, kindergartenWalletReturnUrl(row, 'failed'));
    }
    if (!zibalConfigured)
        return redirect(res, kindergartenWalletReturnUrl(row, 'error'));
    try {
        const verify = await zibalPost('verify', { merchant: ZIBAL_MERCHANT, trackId });
        const vr = Number(verify?.result || 0);
        if (vr !== 100 && vr !== 201) {
            const failureMessage = String(verify?.message || verify?.statusMessage || 'verify_failed').slice(0, 500);
            await pool.query(`UPDATE kindergarten_wallet_gateway_payments SET status='payment_failed',gateway_result=$2,gateway_message=$3,updated_at=now() WHERE id=$1 AND status NOT IN ('paid','credit_pending','credited')`, [row.id, vr, failureMessage]);
            return redirect(res, kindergartenWalletReturnUrl(row, 'failed'));
        }
        const verified = Number(verify?.amount || 0), expected = Number(row.gateway_amount || 0);
        if (verified > 0 && expected > 0 && verified !== expected) {
            await pool.query(`UPDATE kindergarten_wallet_gateway_payments SET status='payment_failed',gateway_result=$2,gateway_message='gateway_amount_mismatch',updated_at=now() WHERE id=$1 AND status NOT IN ('paid','credit_pending','credited')`, [row.id, vr]);
            return redirect(res, kindergartenWalletReturnUrl(row, 'failed'));
        }
        const c = await pool.connect();
        try {
            await c.query('BEGIN');
            const lq = await c.query(`SELECT * FROM kindergarten_wallet_gateway_payments WHERE id=$1 FOR UPDATE`, [row.id]);
            if (!lq.rowCount) {
                await c.query('ROLLBACK');
                return redirect(res, kindergartenWalletReturnUrl(row, 'failed'));
            }
            const current = lq.rows[0];
            if (!['paid', 'credit_pending', 'credited'].includes(String(current.status))) {
                await c.query(`UPDATE kindergarten_wallet_gateway_payments SET status='paid',gateway_track_id=$2,gateway_ref_number=$3,gateway_result=$4,gateway_message=$5,paid_at=COALESCE(paid_at,now()),updated_at=now() WHERE id=$1`, [current.id, trackId, verify?.refNumber != null ? String(verify.refNumber) : null, vr, String(verify?.message || verify?.statusMessage || 'success').slice(0, 500)]);
            }
            await c.query('COMMIT');
        }
        catch (e) {
            await c.query('ROLLBACK').catch(() => { });
            throw e;
        }
        finally {
            c.release();
        }
        return redirect(res, kindergartenWalletReturnUrl(row, 'success'));
    }
    catch (e) {
        console.error('Kindergarten wallet Zibal verify failed', e);
        return redirect(res, kindergartenWalletReturnUrl(row, 'error'));
    }
}
