async function equipmentSaleWalletEnsure(db, shopId) {
    await ensureEquipmentRentalV658Schema();
    await db.query(`INSERT INTO equipment_sale_wallets(shop_id,balance,updated_at) VALUES($1,0,now()) ON CONFLICT(shop_id) DO NOTHING`, [shopId]);
}
async function equipmentSaleWalletSnapshot(shopId) {
    await equipmentSaleWalletEnsure(pool, shopId);
    const [wq,tq] = await Promise.all([
        pool.query(`SELECT balance,updated_at FROM equipment_sale_wallets WHERE shop_id=$1`, [shopId]),
        pool.query(`SELECT id,kind,amount,balance_after,reference_type,reference_id,note,buyer_user_id,created_at FROM equipment_sale_wallet_transactions WHERE shop_id=$1 ORDER BY created_at DESC,id DESC LIMIT 60`, [shopId])
    ]);
    // R100F2: use the newest balance_after when its ledger entry is at least as
    // recent as the cached wallet row. This repairs not only stale zero rows but
    // also the old bug where the header stayed on the initial positive credit
    // after later debits/credits had already been written to the ledger.
    const stored = wq.rows[0]?.balance;
    const latestRow = tq.rows[0] || null;
    const latest = latestRow?.balance_after;
    let balance = stored != null && Number.isFinite(Number(stored))
        ? Number(stored)
        : latest != null && Number.isFinite(Number(latest)) ? Number(latest) : 0;
    const walletUpdatedAt = wq.rows[0]?.updated_at ? new Date(wq.rows[0].updated_at).getTime() : 0;
    const latestTxAt = latestRow?.created_at ? new Date(latestRow.created_at).getTime() : 0;
    if (latest != null && Number.isFinite(Number(latest)) && latestTxAt >= walletUpdatedAt - 1500 && Number(latest) !== Number(balance)) {
        const ledgerBalance = Number(latest);
        const repairedRow = await pool.query(
            `UPDATE equipment_sale_wallets SET balance=$2,updated_at=GREATEST(updated_at,$3::timestamptz) WHERE shop_id=$1 RETURNING balance`,
            [shopId, ledgerBalance, latestRow.created_at]
        );
        balance = Number(repairedRow.rows[0]?.balance ?? ledgerBalance);
    }
    // A paid gateway record may exist from an older deployment without its wallet ledger row.
    if (balance === 0) {
        const repaired = await equipmentSaleWalletRecoverPaidTopups(shopId).catch(()=>null);
        if (repaired && Number(repaired.balance||0) > 0) {
            const rq=await pool.query(`SELECT balance,updated_at FROM equipment_sale_wallets WHERE shop_id=$1`,[shopId]);
            const rt=await pool.query(`SELECT id,kind,amount,balance_after,reference_type,reference_id,note,buyer_user_id,created_at FROM equipment_sale_wallet_transactions WHERE shop_id=$1 ORDER BY created_at DESC,id DESC LIMIT 60`,[shopId]);
            return { balance:Number(rq.rows[0]?.balance||repaired.balance||0), updatedAt:rq.rows[0]?.updated_at||null, transactions:rt.rows };
        }
    }
    return { balance, updatedAt:wq.rows[0]?.updated_at || null, transactions:tq.rows };
}
async function equipmentSaleWalletRecoverPaidTopups(shopId) {
    const c = await pool.connect();
    try {
        await c.query('BEGIN');
        await equipmentSaleWalletEnsure(c, shopId);
        const wq = await c.query(`SELECT balance FROM equipment_sale_wallets WHERE shop_id=$1 FOR UPDATE`, [shopId]);
        let running = Number(wq.rows[0]?.balance || 0), recovered = 0;
        const paid = await c.query(`SELECT id,amount FROM service_wallet_gateway_payments WHERE owner_id=$1 AND status='paid' AND amount>0 AND (owner_type='rental_shop_sales' OR (owner_type='rental_shop' AND COALESCE(return_path,'')='/rental')) ORDER BY COALESCE(paid_at,callback_at,created_at),created_at,id`, [shopId]);
        for (const p of paid.rows) {
            const amount = Math.max(0, Math.round(Number(p.amount || 0))); if (!amount) continue;
            const exists = await c.query(`SELECT 1 FROM equipment_sale_wallet_transactions WHERE shop_id=$1 AND reference_type='zibal_topup' AND (reference_id=$2::text OR reference_key=$3) LIMIT 1`, [shopId,p.id,`zibal:${p.id}`]);
            if (exists.rowCount) continue;
            running += amount; recovered += amount;
            await c.query(`INSERT INTO equipment_sale_wallet_transactions(shop_id,kind,amount,balance_after,reference_type,reference_id,reference_key,note,metadata) VALUES($1,'credit',$2,$3,'zibal_topup',$4::text,$5,$6,$7::jsonb) ON CONFLICT DO NOTHING`, [shopId,amount,running,p.id,`zibal:${p.id}`,'بازیابی شارژ آنلاین کیف پول',JSON.stringify({recoveredBy:'v904R22',paymentId:p.id})]);
        }
        if (recovered > 0) await c.query(`UPDATE equipment_sale_wallets SET balance=$2,updated_at=now() WHERE shop_id=$1`, [shopId,running]);
        await c.query('COMMIT'); return { recovered, balance:running };
    } catch (e) { await c.query('ROLLBACK').catch(()=>{}); throw e; } finally { c.release(); }
}
async function equipmentSaleDebitBuyerAndCreditShop(c, { orderId, shopId, buyerUserId, amount, itemTitle, quantity }) {
    const value = Math.max(0, Math.round(Number(amount || 0)));
    await photographerWalletEnsure(c, buyerUserId);
    await equipmentSaleWalletEnsure(c, shopId);
    const buyerWallet = await c.query(`SELECT balance FROM photographer_service_wallets WHERE user_id=$1 FOR UPDATE`, [buyerUserId]);
    const buyerBalance = Number(buyerWallet.rows[0]?.balance || 0);
    if (buyerBalance < value) {
        const e = new Error('service_wallet_insufficient'); e.balance = buyerBalance; e.required = value; throw e;
    }
    let buyerTx = null, shopTx = null, buyerAfter = buyerBalance;
    if (value > 0) {
        buyerAfter = buyerBalance - value;
        await c.query(`UPDATE photographer_service_wallets SET balance=$2,updated_at=now() WHERE user_id=$1`, [buyerUserId,buyerAfter]);
        const bq = await c.query(`INSERT INTO photographer_service_wallet_transactions(user_id,service_key,kind,amount,balance_after,reference_type,reference_id,reference_key,note,metadata)
          VALUES($1,NULL,'debit',$2,$3,'equipment_sale',$4,$5,$6,$7::jsonb) RETURNING *`, [buyerUserId,value,buyerAfter,orderId,`equipment-sale:${orderId}:buyer`,`خرید تجهیزات · ${itemTitle}`,JSON.stringify({shopId,itemTitle,quantity})]);
        buyerTx = bq.rows[0] || null;
        const sw = await c.query(`SELECT balance FROM equipment_sale_wallets WHERE shop_id=$1 FOR UPDATE`, [shopId]);
        const shopAfter = Number(sw.rows[0]?.balance || 0) + value;
        await c.query(`UPDATE equipment_sale_wallets SET balance=$2,updated_at=now() WHERE shop_id=$1`, [shopId,shopAfter]);
        const sq = await c.query(`INSERT INTO equipment_sale_wallet_transactions(shop_id,kind,amount,balance_after,reference_type,reference_id,reference_key,note,buyer_user_id,metadata)
          VALUES($1,'credit',$2,$3,'equipment_sale',$4,$5,$6,$7,$8::jsonb) RETURNING *`, [shopId,value,shopAfter,orderId,`equipment-sale:${orderId}:shop`,`فروش ${quantity} عدد ${itemTitle}`,buyerUserId,JSON.stringify({itemTitle,quantity})]);
        shopTx = sq.rows[0] || null;
    }
    return { buyerTx, shopTx, buyerBalanceAfter:buyerAfter };
}
async function equipmentSaleRefundPaidOrder(c, order) {
    if (!order || String(order.payment_status || '') !== 'paid' || !order.buyer_user_id) return null;
    const value = Math.max(0, Number(order.total_amount || 0));
    await photographerWalletEnsure(c, order.buyer_user_id); await equipmentSaleWalletEnsure(c, order.shop_id);
    const existing = await c.query(`SELECT id FROM photographer_service_wallet_transactions WHERE user_id=$1 AND reference_key=$2 LIMIT 1`, [order.buyer_user_id,`equipment-sale:${order.id}:refund`]);
    if (existing.rowCount) return { alreadyRefunded:true };
    if (value > 0) {
        const sw = await c.query(`SELECT balance FROM equipment_sale_wallets WHERE shop_id=$1 FOR UPDATE`, [order.shop_id]);
        const shopBalance = Number(sw.rows[0]?.balance || 0);
        if (shopBalance < value) throw Object.assign(new Error('sale_wallet_insufficient_for_refund'), { balance:shopBalance, required:value });
        const shopAfter = shopBalance - value;
        await c.query(`UPDATE equipment_sale_wallets SET balance=$2,updated_at=now() WHERE shop_id=$1`, [order.shop_id,shopAfter]);
        await c.query(`INSERT INTO equipment_sale_wallet_transactions(shop_id,kind,amount,balance_after,reference_type,reference_id,reference_key,note,buyer_user_id,metadata)
          VALUES($1,'refund',$2,$3,'equipment_sale_refund',$4,$5,$6,$7,$8::jsonb)`, [order.shop_id,value,shopAfter,order.id,`equipment-sale:${order.id}:shop-refund`,'برگشت وجه فروش لغوشده',order.buyer_user_id,JSON.stringify({orderId:order.id})]);
        const bw = await c.query(`SELECT balance FROM photographer_service_wallets WHERE user_id=$1 FOR UPDATE`, [order.buyer_user_id]);
        const buyerAfter = Number(bw.rows[0]?.balance || 0) + value;
        await c.query(`UPDATE photographer_service_wallets SET balance=$2,updated_at=now() WHERE user_id=$1`, [order.buyer_user_id,buyerAfter]);
        await c.query(`INSERT INTO photographer_service_wallet_transactions(user_id,service_key,kind,amount,balance_after,reference_type,reference_id,reference_key,note,metadata)
          VALUES($1,NULL,'refund',$2,$3,'equipment_sale_refund',$4,$5,'برگشت وجه خرید تجهیزات',$6::jsonb)`, [order.buyer_user_id,value,buyerAfter,order.id,`equipment-sale:${order.id}:refund`,JSON.stringify({shopId:order.shop_id,orderId:order.id})]);
    }
    return { refunded:true };
}

// PhotoBridge v829 — shop-managed brand list used by rental and sales item modals.
