    const customWidth = customRaw ? Math.round(Number(customRaw.widthCm || 0) * 10) / 10 : 0, customHeight = customRaw ? Math.round(Number(customRaw.heightCm || 0) * 10) / 10 : 0;
    const customSize = String(input?.sizeId || '') === '__custom__' || Boolean(customRaw);
    let size = null;
    if (customSize) {
        if (!Number.isFinite(customWidth) || !Number.isFinite(customHeight) || customWidth <= 0 || customHeight <= 0 || customWidth > 500 || customHeight > 500)
            throw Object.assign(new Error('album_custom_size_invalid'), { status: 400 });
        size = { id: null, label: `${Math.min(customWidth, customHeight)}×${Math.max(customWidth, customHeight)}`, widthCm: customWidth, heightCm: customHeight, minSpreads: 1, maxSpreads: 500, custom: true };
    }
