        throw Object.assign(new Error('album_spreads_invalid'), { status: 400, minSpreads: size.minSpreads, maxSpreads: size.maxSpreads });

    const paperType = String(input?.paperType || '').trim();
    const paperTypes = ['luster', 'silk', 'metallic'];
    if (!paperTypes.includes(paperType))
        throw Object.assign(new Error('album_paper_required'), { status: 400 });
    const rawPaperCounts = input?.paperCounts && typeof input.paperCounts === 'object' ? input.paperCounts : null;
    const paperCounts = {};
    let explicitPaperTotal = 0;
    for (const type of paperTypes) {
        const n = rawPaperCounts ? Math.max(0, Math.floor(Number(rawPaperCounts[type] || 0))) : (type === paperType ? spreads : 0);
        paperCounts[type] = n;
        explicitPaperTotal += n;
    }
    // mixed paper types allowed per file; do not block album send
    const paperBreakdown = paperTypes.filter(type => paperCounts[type] > 0).map(type => {
        const raw = customSize ? null : size[type];
        const known = raw != null && String(raw).trim() !== '' && Number.isFinite(Number(raw));
        const unitPrice = known ? albumMoney(raw) : null;
        return { paperType: type, paperTypeLabel: invoicePrintTypeLabel(type), count: paperCounts[type], unitPrice, lineTotal: unitPrice == null ? null : unitPrice * paperCounts[type] };
    });
    const missingPaperTariff = customSize || paperBreakdown.some(x => x.unitPrice == null);
    const knownPrintTotal = paperBreakdown.reduce((n, x) => n + Number(x.lineTotal || 0), 0);

    const coverCatalogEnabled = catalog.coverCatalogEnabled !== false;
    const customCover = Boolean(input?.customCover) || !coverCatalogEnabled;
    const coverRequest = String(input?.coverRequest || '').trim().slice(0, 1200);
    let cover = null, color = null;
