async function printAlertAgent(req) {
    const token = String(req.headers['x-photobridge-print-agent-token'] || '').trim();
    if (!token || token.length < 32)
        return null;
    const q = await pool.query(`SELECT a.lab_id,a.label,a.enabled,a.web_panel_last_seen_at,(a.web_panel_last_seen_at IS NOT NULL AND a.web_panel_last_seen_at > now()-interval '10 seconds') web_panel_active,l.name lab_name,l.active
    FROM lab_print_alert_agents a JOIN labs l ON l.id=a.lab_id
    WHERE a.token_hash=$1 AND a.enabled=true LIMIT 1`, [tokenHash(token)]).catch(() => ({ rows: [], rowCount: 0 }));
    if (!q.rowCount || !q.rows[0]?.active)
        return null;
    await pool.query(`UPDATE lab_print_alert_agents SET last_seen_at=now(),updated_at=now() WHERE lab_id=$1`, [q.rows[0].lab_id]).catch(() => { });
    return q.rows[0];
}
async function pendingPrintAlerts(labId) {
    const q = await pool.query(`SELECT o.id,o.number,o.updated_at,o.created_at,o.priority,o.delivery,u.name customer_name,
      (SELECT count(*)::int FROM order_files f WHERE f.order_id=o.id AND f.original_state<>'deleted') file_count,
      COALESCE((SELECT sum(f.bytes)::bigint FROM order_files f WHERE f.order_id=o.id AND f.original_state<>'deleted'),0)::bigint total_bytes,
      (SELECT i.total::bigint FROM invoices i WHERE i.order_id=o.id ORDER BY i.created_at DESC LIMIT 1) invoice_total
    FROM orders o LEFT JOIN users u ON u.id=o.customer_id
    WHERE o.lab_id=$1 AND o.status='sent'
      AND (o.settlement_mode<>'prepaid' OR o.payment_status='paid')
      AND o.print_alert_acknowledged_at IS NULL
    ORDER BY o.updated_at ASC LIMIT 80`, [labId]);
    return q.rows;
}
async function acknowledgePrintAlerts(labId, orderIds, actorId, source = 'panel') {
    const ids = [...new Set((orderIds || []).map(String).filter(x => /^[0-9a-f-]{36}$/i.test(x)))];
    if (!ids.length)
        return 0;
    const q = await pool.query(`UPDATE orders SET print_alert_acknowledged_at=COALESCE(print_alert_acknowledged_at,now()),print_alert_acknowledged_by=COALESCE(print_alert_acknowledged_by,$3::uuid),updated_at=updated_at
    WHERE lab_id=$1 AND id=ANY($2::uuid[]) AND print_alert_acknowledged_at IS NULL RETURNING id`, [labId, ids, actorId || null]);
    if (q.rowCount)
        await audit(actorId || undefined, labId, 'print_alert.acknowledge', 'order', undefined, { orderIds: ids, source, count: q.rowCount }).catch(() => { });
    return q.rowCount || 0;
}

