        graph.push({ '@type': 'Service', name: meta.heading, description: meta.description, url: `${SEO_SITE_ORIGIN}${pathname}`, provider: { '@id': `${SEO_SITE_ORIGIN}/#organization` }, areaServed: 'IR' });
        const items = [{ '@type': 'ListItem', position: 1, name: 'PhotoBridge', item: `${SEO_SITE_ORIGIN}/` }];
        if (pathname !== parent) items.push({ '@type': 'ListItem', position: 2, name: parentName, item: `${SEO_SITE_ORIGIN}${parent}` }, { '@type': 'ListItem', position: 3, name: meta.heading, item: `${SEO_SITE_ORIGIN}${pathname}` });
        else items.push({ '@type': 'ListItem', position: 2, name: meta.heading, item: `${SEO_SITE_ORIGIN}${pathname}` });
