function seoInjectHtml(html, pathname) {
    const privatePath = seoPrivatePath(pathname);
    const meta = SEO_PUBLIC_PAGES[pathname] || (privatePath ? null : SEO_PUBLIC_PAGES['/']);
    const canonical = meta ? `${SEO_SITE_ORIGIN}${pathname === '/' ? '/' : pathname}` : '';
    const robots = privatePath ? 'noindex,nofollow,noarchive' : 'index,follow,max-image-preview:large,max-snippet:-1,max-video-preview:-1';
    const title = meta?.title || 'PhotoBridge';
    const description = meta?.description || 'PhotoBridge';
    let next = html
        .replace(/<title>[\s\S]*?<\/title>/i, `<title>${htmlAttr(title)}</title>`)
        .replace(/<meta name="description"[^>]*>/i, `<meta name="description" content="${htmlAttr(description)}"/>`)
        .replace(/<meta name="robots"[^>]*>/i, `<meta name="robots" content="${robots}"/>`)
        .replace(/<link rel="canonical"[^>]*>/i, canonical ? `<link rel="canonical" href="${htmlAttr(canonical)}"/>` : '')
        .replace(/<meta property="og:title"[^>]*>/i, `<meta property="og:title" content="${htmlAttr(title)}"/>`)
        .replace(/<meta property="og:description"[^>]*>/i, `<meta property="og:description" content="${htmlAttr(description)}"/>`)
        .replace(/<meta property="og:url"[^>]*>/i, canonical ? `<meta property="og:url" content="${htmlAttr(canonical)}"/>` : '')
        .replace(/<meta name="twitter:title"[^>]*>/i, `<meta name="twitter:title" content="${htmlAttr(title)}"/>`)
        .replace(/<meta name="twitter:description"[^>]*>/i, `<meta name="twitter:description" content="${htmlAttr(description)}"/>`);
    if (meta) {
        const bootstrap = `<main class="seoBootstrap" dir="rtl"><h1>${htmlAttr(meta.heading)}</h1><p>${htmlAttr(meta.body)}</p><nav><a href="/retouch-photo">روتوش عکس</a> · <a href="/photo-selection-gallery">گالری انتخاب عکس</a> · <a href="/album-design">طراحی آلبوم</a> · <a href="/instagram-post-design">طراحی پست اینستاگرام</a> · <a href="/photo-lab-print">چاپ لابراتوار</a></nav></main>`;
        next = next.replace('<div id="root"></div>', `<div id="root">${bootstrap}</div>`);
        next = next.replace('</head>', `<script type="application/ld+json">${seoStructuredData(pathname, meta)}</script></head>`);
    }
    return next;
}


