async function serveAdminEquipmentRentalPage(req, res) {
    const a = await auth(req);
    if (!requireRole(a, 'platform_admin')) return redirect(res, '/admin/login');
    const full = path.join(DIST_ROOT, 'api', 'admin-equipment-rental.html');
    if (!fs.existsSync(full)) return sendText(res, 503, 'Equipment rental pilot page not found.');
    const html = fs.readFileSync(full, 'utf8');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'content-length': Buffer.byteLength(html), 'cache-control': 'no-store, max-age=0', 'x-robots-tag': 'noindex, nofollow, noarchive' });
    res.end(html);
}

function serveEquipmentRentalPage(res, fileName, robots = 'noindex, nofollow, noarchive') {
    const full = path.join(DIST_ROOT, 'api', fileName);
    if (!fs.existsSync(full)) return sendText(res, 503, 'Equipment rental page not found.');
    const html = fs.readFileSync(full, 'utf8');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'content-length': Buffer.byteLength(html), 'cache-control': 'no-store, max-age=0, must-revalidate', 'pragma': 'no-cache', 'expires': '0', 'x-robots-tag': robots, 'x-photobridge-build': 'v904r100f64', 'x-photobridge-deploy-revision': DEPLOY_REVISION });
    res.end(html);
}

function serveWeb(req, res, pathname) {
    // R88: serve jsQR directly from the installed npm dependency too. This keeps mobile
    // scanning functional even on Node-platform deploys that skip the optional dist copy step.
    if (pathname === '/vendor-jsqr-1.4.0.js') {
        const jsqr = path.join(process.cwd(), 'node_modules', 'jsqr', 'dist', 'jsQR.js');
        if (!fs.existsSync(jsqr)) return sendText(res, 503, 'QR scanner engine not installed.');
        const st = fs.statSync(jsqr);
        res.writeHead(200, { 'content-type':'application/javascript; charset=utf-8', 'content-length':st.size, 'cache-control':'public, max-age=3600, must-revalidate', 'x-content-type-options':'nosniff' });
        fs.createReadStream(jsqr).pipe(res);
        return;
    }
    if (pathname === '/retouch-account') pathname = '/retouch-account.html';
    const standaloneHtml = seoStandaloneHtml(pathname);
    if (standaloneHtml) {
        res.writeHead(200, { 'content-type':'text/html; charset=utf-8', 'cache-control':'no-store', 'content-length':Buffer.byteLength(standaloneHtml), 'x-robots-tag':'index, follow' });
        res.end(standaloneHtml);
        return;
    }
    let rel = pathname === '/' ? 'index.html' : pathname.replace(/^\//, '');
    let full = path.resolve(WEB_DIR, rel);
    if (!full.startsWith(WEB_DIR) || !fs.existsSync(full) || fs.statSync(full).isDirectory())
        full = path.join(WEB_DIR, 'index.html');
    if (!fs.existsSync(full))
        return sendText(res, 503, 'Web build not found. Run npm run build.');
    const st = fs.statSync(full), contentType = mime(full), isIndex = path.basename(full) === 'index.html', isRetouchAccount = path.basename(full) === 'retouch-account.html', isBuildMarker = path.basename(full) === 'photobridge-build.json', streamable = /^(video|audio)\//i.test(contentType), revalidateAsset = /(?:javascript|css)/i.test(contentType), cacheControl = (isIndex || isRetouchAccount || isBuildMarker) ? 'no-store, max-age=0, must-revalidate' : streamable ? 'public, max-age=3600, must-revalidate' : revalidateAsset ? 'no-cache, max-age=0, must-revalidate' : 'public, max-age=31536000, immutable';
    const etag = `W/\"${st.size}-${Math.trunc(st.mtimeMs)}\"`;
    const common = { 'content-type': contentType, 'cache-control': cacheControl, 'etag': etag, 'last-modified': st.mtime.toUTCString(), 'x-photobridge-release': 'v858' };
    if (isIndex) {
        const raw = fs.readFileSync(full, 'utf8');
        const html = seoInjectHtml(raw, pathname);
        res.writeHead(200, { ...common, 'content-length': Buffer.byteLength(html), 'x-robots-tag': seoPrivatePath(pathname) ? 'noindex, nofollow, noarchive' : 'index, follow' });
        res.end(html);
        return;
    }
    if (!String(req.headers.range || '').trim() && String(req.headers['if-none-match'] || '') === etag) {
        res.writeHead(304, common);
        res.end();
        return;
    }
    if (streamable)
        common['accept-ranges'] = 'bytes';
    const rawRange = streamable ? String(req.headers.range || '').trim() : '';
    const m = rawRange.match(/^bytes=(\d*)-(\d*)$/i);
    if (m) {
        let start, end;
        if (m[1]) {
            start = Number(m[1]);
            end = m[2] ? Number(m[2]) : st.size - 1;
        }
        else {
            const suffix = Number(m[2]);
            if (!Number.isFinite(suffix) || suffix <= 0) {
                res.writeHead(416, { 'content-range': `bytes */${st.size}`, 'accept-ranges': 'bytes' });
                res.end();
                return;
            }
            start = Math.max(0, st.size - suffix);
            end = st.size - 1;
        }
        if (!Number.isFinite(start) || !Number.isFinite(end) || start < 0 || start >= st.size || end < start) {
            res.writeHead(416, { 'content-range': `bytes */${st.size}`, 'accept-ranges': 'bytes' });
            res.end();
            return;
        }
        end = Math.min(end, st.size - 1);
        const length = end - start + 1;
        res.writeHead(206, { ...common, 'content-length': length, 'content-range': `bytes ${start}-${end}/${st.size}` });
        if (req.method === 'HEAD') {
            res.end();
            return;
        }
        fs.createReadStream(full, { start, end }).pipe(res);
        return;
    }
    res.writeHead(200, { ...common, 'content-length': st.size });
    if (req.method === 'HEAD') {
        res.end();
        return;
    }
    fs.createReadStream(full).pipe(res);
}
const BUILTIN_ADMIN_MOBILE = '09125678720';
const BUILTIN_ADMIN_PASSWORD_HASH = '0a2e766f956a27fe1a1629e159eb8776:728c5cbc760fd7e9b9e5a5dd8d8a97950c31ce3aff044eb0c72e01a42587e4f0415973036e6da1154eb2d58f94fad4f788ab00e68a04105e5cbbf56bf8c5f37e';
function isRetouchAdminTestMobile(value) {
    const mobile = normalizeMobile(String(value || ''));
    const envMobile = normalizeMobile(process.env.ADMIN_MOBILE || '');
    return Boolean(mobile && (mobile === BUILTIN_ADMIN_MOBILE || (envMobile && mobile === envMobile)));
}
async function seedAdmin() {
    // v0.13.2 recovery bootstrap: apply the initial admin credentials exactly once for this release.
    // After the first successful boot, credentials can be changed from the admin panel
    // and will NOT be reset on later restarts.
    const markerKey = 'admin_bootstrap_v0132';
    const marker = await pool.query('SELECT 1 FROM platform_settings WHERE key=$1 LIMIT 1', [markerKey]);
    if (marker.rowCount)
        return;
    const useEnv = process.env.ADMIN_BOOTSTRAP_USE_ENV === 'true';
    const envMobile = normalizeMobile(process.env.ADMIN_MOBILE || '');
    const envPass = String(process.env.ADMIN_PASSWORD || '');
    const legacyEmail = process.env.ADMIN_EMAIL?.trim().toLowerCase() || '';
    const mobile = useEnv && envMobile ? envMobile : BUILTIN_ADMIN_MOBILE;
    const passHash = useEnv && envPass ? passwordHash(envPass) : BUILTIN_ADMIN_PASSWORD_HASH;
    const name = (process.env.ADMIN_NAME || '').trim() || 'Platform Admin';
    let exists = null;
    if (mobile) {
        const q = await pool.query("SELECT id FROM users WHERE mobile=$1 AND platform_role='platform_admin' LIMIT 1", [mobile]);
        exists = q.rows[0] || null;
    }
    if (!exists) {
        const q = await pool.query("SELECT id FROM users WHERE platform_role='platform_admin' ORDER BY created_at LIMIT 1");
        exists = q.rows[0] || null;
    }
    if (!exists && useEnv && legacyEmail) {
        const q = await pool.query("SELECT id FROM users WHERE lower(email)=$1 AND platform_role='platform_admin' LIMIT 1", [legacyEmail]);
        exists = q.rows[0] || null;
    }
    if (!exists) {
        const q = await pool.query(`INSERT INTO users(name,email,mobile,password_hash,platform_role) VALUES($1,$2,$3,$4,'platform_admin') RETURNING id`, [name, useEnv && legacyEmail ? legacyEmail : null, mobile, passHash]);
        exists = q.rows[0];
    }
    else {
        await pool.query(`UPDATE users SET name=$2,mobile=$3,password_hash=$4,platform_role='platform_admin',active=true,updated_at=now() WHERE id=$1`, [exists.id, name, mobile, passHash]);
    }
    await pool.query(`INSERT INTO platform_settings(key,value,updated_at) VALUES($1,$2::jsonb,now()) ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value,updated_at=now()`, [markerKey, JSON.stringify({ applied: true })]);
    console.log('Platform admin bootstrap applied.');
}
async function labOpenStatus(labId) {
    const lab = (await pool.query('SELECT timezone,active,active_from,active_until FROM labs WHERE id=$1', [labId])).rows[0];
    if (!lab)
        return { open: false, reason: 'not_found' };
    if (!lab.active)
        return { open: false, reason: 'inactive' };
    const now = new Date();
    if (lab.active_from && now < new Date(lab.active_from))
        return { open: false, reason: 'not_started' };
    if (lab.active_until && now > new Date(lab.active_until))
        return { open: false, reason: 'subscription_expired' };
    const parts = new Intl.DateTimeFormat('en-CA', { timeZone: lab.timezone || 'Asia/Tehran', weekday: 'short', hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(now);
    const wd = parts.find(x => x.type === 'weekday')?.value;
    const map = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
    const hh = parts.find(x => x.type === 'hour')?.value || '00';
    const mm = parts.find(x => x.type === 'minute')?.value || '00';
    const time = `${hh}:${mm}`;
    const r = (await pool.query('SELECT enabled,open_time::text,close_time::text FROM working_hours WHERE lab_id=$1 AND weekday=$2', [labId, map[wd || 'Sun']])).rows[0];
    if (!r || !r.enabled)
        return { open: false, reason: 'closed_today' };
    const open = String(r.open_time).slice(0, 5), close = String(r.close_time).slice(0, 5);
    return { open: time >= open && time <= close, reason: time >= open && time <= close ? 'open' : 'outside_hours', openTime: open, closeTime: close };
}
async function createSessionToken(userId, lifetime = `${DAYS} days`) { const raw = crypto.randomBytes(32).toString('base64url'); await pool.query('INSERT INTO sessions(user_id,token_hash,expires_at) VALUES($1,$2,now()+$3::interval)', [userId, tokenHash(raw), lifetime]); return raw; }
async function createSession(userId, res, portal = 'default') { const raw = await createSessionToken(userId); setSessionCookie(res, raw, portal); }
async function customerBelongsToLab(labId, customerId) { const q = await pool.query(`SELECT 1 WHERE EXISTS(SELECT 1 FROM lab_memberships WHERE lab_id=$1 AND user_id=$2 AND role='customer') OR EXISTS(SELECT 1 FROM invoices WHERE lab_id=$1 AND customer_id=$2)`, [labId, customerId]); return Boolean(q.rowCount); }
async function ensurePhotographerGalleryAccess(userId) {
    await pool.query(`INSERT INTO photographer_gallery_access(user_id,enabled,plan_code,plan_status) VALUES($1,true,'payg','active') ON CONFLICT(user_id) DO NOTHING`, [userId]);
    const q = await pool.query(`SELECT enabled,plan_code,plan_status,active_until FROM photographer_gallery_access WHERE user_id=$1 LIMIT 1`, [userId]);
    return q.rows[0] || { enabled: false, plan_code: 'payg', plan_status: 'disabled', active_until: null };
}
