                    correction = cq.rows[0];
                    if (financeMoneyAccountKey(old.method) !== financeMoneyAccountKey(newMethod))
                        transactionId = await postBalancedFinanceTransaction(c, { labId, actorId: a.userId, description: 'اصلاح روش دریافت', referenceType: 'finance_correction', referenceId: correction.id, lines: [{ accountKey: financeMoneyAccountKey(newMethod), customerId: old.customer_id, debit: Number(old.amount), note: 'انتقال به روش صحیح' }, { accountKey: financeMoneyAccountKey(old.method), customerId: old.customer_id, credit: Number(old.amount), note: 'برگشت روش قبلی' }] });
                    await c.query(`UPDATE finance_payments SET method=$2,note=COALESCE(note,'')||$3 WHERE id=$1`, [targetId, newMethod, `\n[اصلاحیه #${correction.document_number}] ${note}`]);
