                if (current.settlement_mode === 'prepaid' && String(current.payment_status || '') !== 'paid' && !current.downloaded_at) {
                    await c.query('ROLLBACK');
                    return sendJson(res, 409, { error: 'payment_required' });
                }
                const uq = await c.query(`UPDATE orders SET
          downloaded_at=COALESCE(downloaded_at,now()),
          album_stage=CASE WHEN album_stage IN ('binding','ready','completed') THEN album_stage ELSE 'printing' END,
          status=CASE WHEN status IN ('ready','completed') THEN status ELSE 'printing' END,
          updated_at=now()
          WHERE id=$1 AND lab_id=$2 AND mode='album' RETURNING *`, [orderId, labId]);
                order = uq.rows[0];
