                const recoveryEvent = { orderId: newOrderId, number: newOrder.number, sourceOrderId: sourceOrder.id, sourceOrderNumber: sourceOrder.number, invoiceRequired, fileCount: prepared.length, localRecovery: false, createdAt: new Date().toISOString() };
