                pool.query(`SELECT COALESCE(sum(amount),0)::bigint total,count(*)::int count FROM finance_payments WHERE lab_id=$1 AND customer_id=$2`, [labId, a.userId]),
                pool.query(`SELECT COALESCE(sum(amount),0)::bigint total,count(*)::int count FROM finance_customer_adjustments WHERE lab_id=$1 AND customer_id=$2`, [labId, a.userId]),
                pool.query(`SELECT COALESCE(sum(e.debit-e.credit),0)::bigint balance FROM finance_entries e JOIN finance_accounts a ON a.id=e.account_id WHERE a.lab_id=$1 AND a.system_key='receivable' AND e.customer_id=$2`, [labId, a.userId])
