            notifyLabManagerSms(labId, 'manager_chat', { messageId: q.rows[0].id, senderId: a.userId, senderName: a.name, message }).catch(e => console.error('Lab manager chat SMS failed', e?.message || e));
            return sendJson(res, 201, { message: q.rows[0] });
